  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 2: Simulating a simple circuit (Tinkercad)$t$,$t$Log in to the SmartBrains Tinkercad dashboard and simulate a simple circuit before building it for real.$t$,2) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$Open the SmartBrains Tinkercad dashboard$t$,$t$<p><strong>🎯 Objective:</strong> Log in to the SmartBrains Tinkercad dashboard and start a new circuit.</p><p>Tinkercad is a free website where you can build and test circuits on the screen, so nothing can burn. It opens in your browser, so keep this lesson open in one tab and Tinkercad in another.</p><h3>Steps</h3><ol><li>Open the SmartBrains Tinkercad dashboard and log in.</li><li>Create a new circuit.</li><li>Click the field next to <strong>Name</strong> and type a name for your project.</li></ol><p><strong>[[VERIFY: Add the school's Tinkercad login link and login steps. The client notes do not include them.]]</strong></p>$t$,null,$t$You can rename your project by editing the field next to "Name".$t$,1,8),
    (m,$t$Find and place your components$t$,$t$<p><strong>🎯 Objective:</strong> Search for components and place them in the workspace.</p><p>Use the search box to find each component, then drag it into the workspace.</p><ul><li>SmartBrains Arduino</li><li>Breadboard (the small one)</li><li>LED (you need three)</li><li>Resistors</li></ul><h3>Steps</h3><ol><li>Drag the SmartBrains Arduino to the workspace.</li><li>Drag the small breadboard to the workspace.</li><li>Drag three LEDs, one by one, to the workspace.</li><li>Click each LED and change its colour to red, yellow and green.</li></ol><p>To remove a part you do not want, select it and click the <strong>Trash Bin</strong>.</p>$t$,null,$t$Wrong part? Select it and use the Trash Bin.$t$,2,10),
    (m,$t$Wire the simple circuit$t$,$t$<p><strong>🎯 Objective:</strong> Connect the three LEDs to the SmartBrains Arduino in the simulator.</p><h3>Steps</h3><ol><li>Find the <strong>GND</strong> and <strong>3.3V</strong> ports on the SmartBrains Arduino.</li><li>Connect a pin-to-pin wire to the GND port.</li><li>Connect another pin-to-pin wire to the 3.3V port.</li><li>Join those wires to the negative and positive ports of the breadboard, as shown in the picture.</li><li>Connect a resistor to the longer leg (positive, anode) of an LED. Connect the resistor's wire to a digital pin.</li><li>Connect the shorter leg (negative, cathode) of the LED to GND.</li><li>Repeat for the other two LEDs.</li></ol><p><em>📷 Picture to be added: the finished simulated circuit with three LEDs</em></p><p><strong>[[VERIFY: The Lesson 2 quiz in the client notes says the anode is connected to 3.3V, but these steps connect it through a resistor to a digital pin. Confirm which wiring is correct and make the steps and quiz match.]]</strong></p><h3>Check yourself</h3><ul><li>Which leg of the LED did the resistor go on?</li><li>Where did the shorter leg go?</li></ul>$t$,null,$t$Resistor on the longer leg. Shorter leg to GND.$t$,3,15),
    (m,$t$Run the simulation$t$,$t$<p><strong>🎯 Objective:</strong> Start the simulation and check that your LEDs light up.</p><h3>Steps</h3><ol><li>Click <strong>Start Simulation</strong>.</li><li>Check whether the LEDs light up.</li></ol><p>If your LEDs do not light up, check that every wire is in the right place, then raise your hand for help.</p>$t$,null,$t$Start Simulation is the button that starts your circuit.$t$,4,6);
