  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 4: Assembling a traffic light$t$,$t$Assemble a traffic light model, wire it up and code it.$t$,4) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$What you need$t$,$t$<p><strong>🎯 Objective:</strong> Gather everything for the traffic light project.</p><h3>You need</h3><ul><li>SmartBrains Arduino</li><li>3 LEDs (red, yellow and green)</li><li>Traffic light assembling box (pieces 1 to 5 and connectors)</li><li>Jumper wires</li><li>USB cable</li></ul><p>You do <strong>not</strong> need a breadboard for this project.</p>$t$,null,$t$No breadboard for the traffic light.$t$,1,5),
    (m,$t$Assemble the box$t$,$t$<p><strong>🎯 Objective:</strong> Put the traffic light box together and fit the board inside.</p><h3>Steps</h3><ol><li>Attach piece 2 to piece 1 on the left, and piece 3 on the right, to form the first part of the box.</li><li>Attach one connector at the base of piece 1 and one at the base of piece 3.</li><li>Place the SmartBrains Arduino inside the box. Make sure the USB port is visible from the left side.</li></ol><p><em>📷 Picture to be added: pieces 1 to 3 joined with connectors</em></p><p><em>📷 Picture to be added: the SmartBrains Arduino inside the box with the USB port on the left</em></p>$t$,null,$t$The USB port must be visible from the left side.$t$,2,15),
    (m,$t$Wire the LEDs$t$,$t$<p><strong>🎯 Objective:</strong> Connect the three LEDs to the correct pins.</p><h3>Steps</h3><ol><li>Connect three jumper wires to the GND ports of the SmartBrains Arduino.</li><li>Stick the three LEDs upright on the marked part of piece 4.</li><li>Connect the GND wires to the <strong>shorter legs</strong> (negative) of the three LEDs.</li><li>Connect the <strong>longer leg</strong> (positive) of each LED to its digital pin, using the table below.</li></ol><table><thead><tr><th>LED</th><th>Longer leg connects to</th></tr></thead><tbody><tr><td>Red</td><td>Digital pin 8</td></tr><tr><td>Yellow</td><td>Digital pin 9</td></tr><tr><td>Green</td><td>Digital pin 10</td></tr></tbody></table><p><em>📷 Picture to be added: the wiring: red to pin 8, yellow to pin 9, green to pin 10</em></p><p><strong>[[VERIFY: The notes say "Connect 3 pins to the port to all the GNDs". Confirm how many GND pins are used and add a picture.]]</strong></p>$t$,null,$t$Red 8, Yellow 9, Green 10. Shorter legs to GND.$t$,3,15),
    (m,$t$Close the box and connect the USB$t$,$t$<p><strong>🎯 Objective:</strong> Finish the box and power your traffic light.</p><h3>Steps</h3><ol><li>Cover the box with piece 5.</li><li>Add another connector at the top of the box to complete it.</li><li>Plug the USB cable into the SmartBrains Arduino USB port, visible on the left side.</li><li>Connect the other end to your laptop.</li></ol>$t$,null,$t$Cover with piece 5, then connect the USB.$t$,4,8),
    (m,$t$Code the traffic light$t$,$t$<p><strong>🎯 Objective:</strong> Write a program that makes the LEDs work like a traffic light, and upload it.</p><p>A traffic light follows a pattern: red, then yellow, then green, then yellow again. Your program turns each LED on, waits, then turns it off.</p><p><em>📷 Picture to be added: the block code for the traffic light</em></p><p>Here is the same program written as Arduino code. Look for the pin numbers 8, 9 and 10 and the <code>delay</code> lines. A delay is a wait, in milliseconds (1000 = 1 second).</p><pre><code>const int RED = 8;
